Q: Angular - Send form on enter in MatDialog A: <p>You just have to pass values of your form when you close your dialog here</p>
<pre><code>export class EditUserComponent {
  public formData = new FormGroup({
    name: new FormControl('', Validators.required),
    age: new FormControl('', Validators.required),
  });

  constructor(public dialogRef: MatDialogRef&lt;EditUserComponent&gt;) {}

  public cancel() {
    this.dialogRef.close();
  }

  public save() {
    if (this.formData.valid) {
      console.log('User is updated');
      this.dialogRef.close(this.formData.values);
    }
  }
}
</code></pre>
<p>And subscribe to close observable in the component where you call dialog.open()</p>
<pre><code>public openDialog() {
const dialogRef = this.dialog.open(EditUserComponent, {
  width: '100%',
  height: '100%',
});

dialogRef.close.pipe(tap(values =&gt; saveForm(values)), takeUntilDestroy(this.destroyRef)).subscribe()
}
</code></pre>

Q: How can I solve an objective with multiple products of continuous decision variables in CPLEX OPL? A: <p>you can write the following model that works fine.</p>
<pre><code>
`execute
{
  cplex.optimalitytarget=3;
} 

 int T = 4;  
range TRange = 1..T;

int ncs=2;
range crange=1..ncs;

int nv=3;
range vrange=1..nv;

dvar float+ x[TRange][vrange][crange];
dvar float+ y[TRange][crange];
dvar float+ w[TRange][crange];
dvar float+ s[TRange][crange];


minimize sum(t in TRange, c in crange, v in vrange)(x[t][v][c]*y[t][c]+s[t][c]*w[t][c]);
subject to{
  forall(t in TRange, c in crange, v in vrange){
  0&lt;=x[t][v][c]&lt;=50;
  1.2*w[t][c]&lt;=y[t][c];
  y[t][c]&lt;=2.5*w[t][c];
     1.1 &lt;= w[t][c]&lt;=3.3;
     0&lt;=s[t][c]&lt;=300;
}  
}`
</code></pre>
